package de.rub.nds.tlsattacker.core.quic.frame;

import de.rub.nds.modifiablevariable.ModifiableVariableFactory;
import de.rub.nds.modifiablevariable.ModifiableVariableHolder;
import de.rub.nds.modifiablevariable.ModifiableVariableProperty;
import de.rub.nds.modifiablevariable.longint.ModifiableLong;
import de.rub.nds.tlsattacker.core.layer.data.DataContainer;
import de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType;
import de.rub.nds.tlsattacker.core.quic.parser.frame.QuicFrameParser;
import de.rub.nds.tlsattacker.core.quic.serializer.frame.QuicFrameSerializer;
import java.io.InputStream;

public abstract class QuicFrame extends ModifiableVariableHolder implements DataContainer {

    protected boolean ackEliciting = true;

    @ModifiableVariableProperty private ModifiableLong frameType;

    public QuicFrame() {}

    public QuicFrame(QuicFrameType quicFrameType) {
        setFrameType(quicFrameType.getValue());
    }

    public void setFrameType(QuicFrameType frameType) {
        this.frameType =
                ModifiableVariableFactory.safelySetValue(this.frameType, frameType.getValue());
    }

    public void setFrameType(ModifiableLong frameType) {
        this.frameType = frameType;
    }

    public void setFrameType(long frameType) {
        this.frameType = ModifiableVariableFactory.safelySetValue(this.frameType, frameType);
    }

    public ModifiableLong getFrameType() {
        return this.frameType;
    }

    public boolean isAckEliciting() {
        return ackEliciting;
    }

    @Override
    public String toCompactString() {
        if (frameType == null) {
            // After an Exception occurred, the frameType can be null in certain circumstances
            // This yielded secondary Exceptions in the toString() method and can result in uncaught
            // Exceptions
            return "NULL";
        }
        String name = QuicFrameType.getFrameType(frameType.getValue()).getName();
        if (name.endsWith("_FRAME")) {
            return name.substring(0, name.length() - "_FRAME".length());
        }
        return name;
    }



    public abstract QuicFrameSerializer getSerializer();



    public abstract QuicFrameParser getParser(InputStream stream);
}
